"""Sales transaction model."""

from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class SalesRecord:
    """Represent one line item from a retail sales CSV file."""

    order_id: str
    order_date: date
    product_name: str
    category: str
    quantity: int
    unit_price: float
    region: str
    payment_method: str

    def revenue(self) -> float:
        """Return the revenue generated by this line item."""
        return self.quantity * self.unit_price

